-- Actual KSP11 export; synthetic migration fixtures, not publisher data.
CREATE TABLE IF NOT EXISTS `deck_undo_link` (`provider` TEXT NOT NULL, `deck_id` TEXT NOT NULL, `link_revision` INTEGER NOT NULL, `before_revision` INTEGER NOT NULL, `previous_link_revision` INTEGER, PRIMARY KEY(`provider`, `deck_id`, `link_revision`), FOREIGN KEY(`provider`, `deck_id`, `link_revision`) REFERENCES `deck_revision`(`provider`, `deck_id`, `revision`) ON UPDATE NO ACTION ON DELETE NO ACTION , FOREIGN KEY(`provider`, `deck_id`, `before_revision`) REFERENCES `deck_revision`(`provider`, `deck_id`, `revision`) ON UPDATE NO ACTION ON DELETE NO ACTION , FOREIGN KEY(`provider`, `deck_id`, `previous_link_revision`) REFERENCES `deck_undo_link`(`provider`, `deck_id`, `link_revision`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_deck_undo_link_before` ON `deck_undo_link` (`provider`, `deck_id`, `before_revision`);
CREATE INDEX IF NOT EXISTS `index_deck_undo_link_previous` ON `deck_undo_link` (`provider`, `deck_id`, `previous_link_revision`);
CREATE TABLE IF NOT EXISTS `deck_undo_state` (`provider` TEXT NOT NULL, `deck_id` TEXT NOT NULL, `head_revision` INTEGER NOT NULL, `undo_link_revision` INTEGER, PRIMARY KEY(`provider`, `deck_id`), FOREIGN KEY(`provider`, `deck_id`, `head_revision`) REFERENCES `deck_revision`(`provider`, `deck_id`, `revision`) ON UPDATE NO ACTION ON DELETE NO ACTION , FOREIGN KEY(`provider`, `deck_id`, `undo_link_revision`) REFERENCES `deck_undo_link`(`provider`, `deck_id`, `link_revision`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_deck_undo_state_head` ON `deck_undo_state` (`provider`, `deck_id`, `head_revision`);
CREATE INDEX IF NOT EXISTS `index_deck_undo_state_link` ON `deck_undo_state` (`provider`, `deck_id`, `undo_link_revision`);
CREATE TABLE IF NOT EXISTS `deck_head` (`provider` TEXT NOT NULL, `deck_id` TEXT NOT NULL, `revision` INTEGER NOT NULL, `name` TEXT NOT NULL, `created_seconds` INTEGER NOT NULL, `created_nano` INTEGER NOT NULL, `modified_seconds` INTEGER NOT NULL, `modified_nano` INTEGER NOT NULL, `entry_count` INTEGER NOT NULL, `total_quantity` INTEGER NOT NULL, PRIMARY KEY(`provider`, `deck_id`));
CREATE TABLE IF NOT EXISTS `deck_revision` (`provider` TEXT NOT NULL, `deck_id` TEXT NOT NULL, `revision` INTEGER NOT NULL, `name` TEXT NOT NULL, `created_seconds` INTEGER NOT NULL, `created_nano` INTEGER NOT NULL, `modified_seconds` INTEGER NOT NULL, `modified_nano` INTEGER NOT NULL, `entry_count` INTEGER NOT NULL, `total_quantity` INTEGER NOT NULL, `payload_bytes` INTEGER NOT NULL, `payload_sha256` TEXT NOT NULL, `payload` BLOB NOT NULL, PRIMARY KEY(`provider`, `deck_id`, `revision`), FOREIGN KEY(`provider`, `deck_id`) REFERENCES `deck_head`(`provider`, `deck_id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE TABLE IF NOT EXISTS `deck_operation` (`sequence` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `operation_id` TEXT NOT NULL, `request_version` INTEGER NOT NULL, `request_sha256` TEXT NOT NULL, `kind` TEXT NOT NULL, `provider` TEXT NOT NULL, `deck_id` TEXT NOT NULL, `result_revision` INTEGER NOT NULL, FOREIGN KEY(`provider`, `deck_id`, `result_revision`) REFERENCES `deck_revision`(`provider`, `deck_id`, `revision`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE UNIQUE INDEX IF NOT EXISTS `index_deck_operation_id` ON `deck_operation` (`operation_id`);
CREATE INDEX IF NOT EXISTS `index_deck_operation_result` ON `deck_operation` (`provider`, `deck_id`, `result_revision`);
CREATE TABLE IF NOT EXISTS `catalog_generation` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `format` TEXT NOT NULL, `content_uri` TEXT NOT NULL, `display_name` TEXT NOT NULL, `source_uri` TEXT, `source_version` TEXT, `source_date_epoch_seconds` INTEGER, `source_date_nano` INTEGER, `observed_at_epoch_seconds` INTEGER NOT NULL, `observed_at_nano` INTEGER NOT NULL, `content_sha256` TEXT NOT NULL, `observed_bytes` INTEGER NOT NULL, `language_scope` TEXT NOT NULL, `payload_schema_version` INTEGER NOT NULL, `parser_version` TEXT NOT NULL, `notice_payload` TEXT, `oracle_count` INTEGER NOT NULL, `face_count` INTEGER NOT NULL, `printing_count` INTEGER NOT NULL, `status` TEXT NOT NULL, `activated_at_epoch_seconds` INTEGER, `activated_at_nano` INTEGER, `input_kind` TEXT NOT NULL DEFAULT 'USER_CONTENT_URI', `artifact_job_id` TEXT, `source_payload` TEXT, PRIMARY KEY(`generation_id`));
